  const g = esc(sep);
  if (grouping === 'none') return '\\d+';
  if (grouping === 'indian') return `(?:\\d{1,3}|\\d{1,2}(?:${g}\\d{2})*${g}\\d{3})`;
  return `\\d{1,3}(?:${g}\\d{3})*`;
}

